#include "memory_map_monitor.h"
#include <iostream>
#include <cstring>

// Include the generated bytecode header
#include "mmap_monitor_bytecode.h"

namespace ebpf {

MemoryMapMonitor::~MemoryMapMonitor() {
    stop();
    detachTracepoints();
    
    if (obj_) {
        bpf_object__close(obj_);
        obj_ = nullptr;
    }
}

bool MemoryMapMonitor::initialize() {
    std::cout << "Memory Map Monitor: Initializing mmap eBPF monitoring..." << std::endl;
    
    if (!loadMMapProgram()) {
        std::cerr << "Memory Map Monitor: Failed to load eBPF program" << std::endl;
        return false;
    }
    
    if (!attachTracepoints()) {
        std::cerr << "Memory Map Monitor: Failed to attach kprobes" << std::endl;
        return false;
    }
    
    std::cout << "Memory Map Monitor: Initialization successful" << std::endl;
    return true;
}

bool MemoryMapMonitor::loadMMapProgram() {
    // Load the mmap eBPF program
    obj_ = bpf_object__open_mem(mmap_monitor_o, mmap_monitor_o_len, nullptr);
    if (!obj_) {
        std::cerr << "Memory Map Monitor: Failed to open eBPF object" << std::endl;
        return false;
    }

    // Load the program into the kernel
    int ret = bpf_object__load(obj_);
    if (ret) {
        std::cerr << "Memory Map Monitor: Failed to load eBPF object: " << ret << std::endl;
        bpf_object__close(obj_);
        obj_ = nullptr;
        return false;
    }

    std::cout << "Memory Map Monitor: eBPF program loaded successfully" << std::endl;
    return true;
}

bool MemoryMapMonitor::attachTracepoints() {
    if (!obj_) {
        std::cerr << "Memory Map Monitor: No eBPF object to attach" << std::endl;
        return false;
    }

    // Define the kprobes we want to attach
    const char* kprobe_functions[] = {
        "sys_mmap",
        "sys_munmap", 
        "sys_msync",
        "do_sys_open",
        "sys_mprotect"
    };
    
    int attached_count = 0;
    int total_count = sizeof(kprobe_functions) / sizeof(kprobe_functions[0]);

    for (int i = 0; i < total_count; i++) {
        const char* func_name = kprobe_functions[i];
        
        // Find the program by name
        std::string prog_name = "trace_" + std::string(func_name);
        
        // Handle special cases for program names
        if (strcmp(func_name, "do_sys_open") == 0) {
            prog_name = "trace_sys_open";
        }
        
        struct bpf_program *prog = bpf_object__find_program_by_name(obj_, prog_name.c_str());
        if (!prog) {
            std::cerr << "Memory Map Monitor: Warning - Program " << prog_name << " not found" << std::endl;
            continue;
        }

        // Attach kprobe
        struct bpf_link *link = bpf_program__attach_kprobe(prog, false, func_name);
        if (link) {
            kprobe_links_.push_back(link);
            attached_count++;
            std::cout << "Memory Map Monitor: Attached kprobe to " << func_name << std::endl;
        } else {
            std::cerr << "Memory Map Monitor: Warning - Failed to attach kprobe to " << func_name << std::endl;
        }
    }

    std::cout << "Memory Map Monitor: Attached " << attached_count << "/" << total_count << " kprobes" << std::endl;
    
    // Return true if we attached at least some kprobes
    return attached_count > 0;
}

void MemoryMapMonitor::detachTracepoints() {
    for (auto* link : kprobe_links_) {
        if (link) {
            bpf_link__destroy(link);
        }
    }
    kprobe_links_.clear();
    std::cout << "Memory Map Monitor: All kprobes detached" << std::endl;
}

bool MemoryMapMonitor::start() {
    if (!obj_) {
        std::cerr << "Memory Map Monitor: No eBPF object loaded" << std::endl;
        return false;
    }

    // Get the ring buffer map
    int ringbuf_fd = bpf_object__find_map_fd_by_name(obj_, "mmap_events");
    if (ringbuf_fd < 0) {
        std::cerr << "Memory Map Monitor: Failed to find mmap_events ring buffer map" << std::endl;
        return false;
    }

    // Create ring buffer
    ring_buf_ = ring_buffer__new(ringbuf_fd, handleRingBufferEvent, this, nullptr);
    if (!ring_buf_) {
        std::cerr << "Memory Map Monitor: Failed to create ring buffer" << std::endl;
        return false;
    }

    // Start polling thread
    is_running_ = true;
    polling_thread_ = std::thread(&MemoryMapMonitor::ringBufferPollLoop, this);
    
    std::cout << "Memory Map Monitor: Started successfully" << std::endl;
    std::cout << "Memory Map Monitor: Ring buffer polling started" << std::endl;
    return true;
}

void MemoryMapMonitor::stop() {
    if (is_running_) {
        is_running_ = false;
        
        if (polling_thread_.joinable()) {
            polling_thread_.join();
        }
        
        std::cout << "Memory Map Monitor: Ring buffer polling stopped" << std::endl;
    }
    
    if (ring_buf_) {
        ring_buffer__free(ring_buf_);
        ring_buf_ = nullptr;
    }
    
    std::cout << "Memory Map Monitor stopped" << std::endl;
}

void MemoryMapMonitor::setEventHandler(std::function<void(const vfs_event&)> handler) {
    event_handler_ = handler;
}

void MemoryMapMonitor::ringBufferPollLoop() {
    while (is_running_) {
        int ret = ring_buffer__poll(ring_buf_, 100); // 100ms timeout
        if (ret < 0 && ret != -EINTR) {
            std::cerr << "Memory Map Monitor: Ring buffer polling error: " << ret << std::endl;
            break;
        }
    }
}

int MemoryMapMonitor::handleRingBufferEvent(void *ctx, void *data, size_t data_sz) {
    MemoryMapMonitor *monitor = static_cast<MemoryMapMonitor*>(ctx);
    
    // Accept mmap events - handle both possible sizes due to struct packing differences
    if (data_sz == 4120 || data_sz == sizeof(vfs_event)) {
        struct vfs_event *event = static_cast<struct vfs_event*>(data);
        
        // Debug output for MMap events
        std::cout << "[MMAP] PID:" << event->pid 
                  << " Action:" << (int)event->action 
                  << " Path:" << event->path << std::endl;
        
        // Call the event handler if set
        if (monitor->event_handler_) {
            monitor->event_handler_(*event);
        }
        return 0;
    }
    
    // Debug: Log unexpected sizes occasionally for troubleshooting
    static int debug_counter = 0;
    if (++debug_counter % 1000 == 0) {
        std::cout << "Memory Map Debug: Received " << debug_counter 
                  << " events with size " << data_sz 
                  << " (expected 4120)" << std::endl;
    }
    
    return 0;
}

} // namespace ebpf 